import{_ as a,o as l,c as s,a4 as t}from"./chunks/framework.CAgiNEKA.js";const C=JSON.parse('{"title":"Claude Code 报 messages is null / status_code=500 怎么解决？","description":"","frontmatter":{"title":"Claude Code 报 messages is null / status_code=500 怎么解决？","date":"2026-06-11T00:00:00.000Z","category":"常见问题","tags":["Claude Code","status_code 500","messages is null","报错处理"]},"headers":[],"relativePath":"faq/claude-code-messages-null-500.md","filePath":"faq/claude-code-messages-null-500.md","lastUpdated":null}'),d={name:"faq/claude-code-messages-null-500.md"};function o(i,e,n,u,r,c){return l(),s("div",null,[...e[0]||(e[0]=[t('<h2 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h2><p>使用 Claude Code 或相关 Claude Plugin 调用模型时，可能会看到类似报错：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>status_code=500, Cannot invoke &quot;***.***.***.***.***.***.setModel(String)&quot; because &quot;messages&quot; is null</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个报错一般不是 API Key 错误，也不是余额或权限问题，而是客户端或插件生成的请求格式与当前模型不兼容。</p><h2 id="常见原因" tabindex="-1">常见原因 <a class="header-anchor" href="#常见原因" aria-label="Permalink to &quot;常见原因&quot;">​</a></h2><p>Claude 发布新模型时，通常会同步升级 Claude Code CLI 或对应的 Claude Agent / Plugin，用来适配新的模型参数、请求结构和工具调用逻辑。</p><p>如果本地 Claude Code CLI 或 Claude Plugin 版本较旧，继续调用新模型时，可能会生成不完整或不兼容的请求体，导致服务端在处理模型字段时发现 <code>messages</code> 为空，从而返回 <code>500</code> 错误。</p><h2 id="解决方法" tabindex="-1">解决方法 <a class="header-anchor" href="#解决方法" aria-label="Permalink to &quot;解决方法&quot;">​</a></h2><p>优先建议升级 Claude Code CLI 或对应的 Claude Plugin 到最新版本。</p><p>升级后，请重启 Claude Code 或对应客户端，再重新发起请求。</p><h2 id="仍然报错怎么办" tabindex="-1">仍然报错怎么办？ <a class="header-anchor" href="#仍然报错怎么办" aria-label="Permalink to &quot;仍然报错怎么办？&quot;">​</a></h2><ol><li><p>确认 Claude Code CLI 或 Claude Plugin 已升级到最新版本。</p></li><li><p>升级后完全重启客户端，不要只刷新当前会话。</p></li><li><p>如果只在某个新模型上报错，可以先切换到稳定模型验证配置是否正常。</p></li><li><p>如果升级后仍然出现同样问题，请将完整报错、客户端版本和使用的模型名称发给客服排查。</p></li></ol>',12)])])}const h=a(d,[["render",o]]);export{C as __pageData,h as default};
